      "body": [
        "751年、アッバース朝が<span class=\"source-red-bold\">タラス</span><ruby><span class=\"source-red-bold\">河畔</span><rt>かはん</rt></ruby><span class=\"source-red-bold\">の戦い</span>で唐を破ると中央アジアにイスラームが広がり、さらに9世紀後半にはウイグルが滅亡して、中央アジアにトルコ人が多数移動してきた。こうした状況下で、9世紀ころからアッバース朝は<span class=\"source-red-bold\">マムルーク</span>と呼ばれるトルコ人奴隷出身の軍人で強力な<ruby><span class=\"source-bold\">騎馬</span><rt>きば</rt></ruby><span class=\"source-bold\">軍団</span>を編成し、カリフの親衛隊をつくった。彼らはイスラームに改宗してカリフに絶対の忠誠を誓ったから、トルコ人のイスラーム化が進んだよ。ただ、奴隷といっても強制労働をするわけじゃないよ。マムルークは君主の側近で、実力が認められると司令官や総督になる支配階級だ！"
      ],
