      "body": [
        "奴隷王朝のあと、ハルジー朝、トゥグルク朝、サイイド朝、ロディー朝と<span class=\"source-red-bold\">デリー</span>を都とする王朝が続き、この5王朝をまとめて<span class=\"source-red-bold\">デリー＝スルタン朝</span>と呼ぶんだ。最低限、王朝の順番はおさえてね！　あとは、基本的にはトルコ系王朝で、最後のロディー朝だけアフガン系ということと、ティムールの侵攻を受け、さらにイブン＝バットゥータがきたのがトゥグルク朝ということは覚えておこう。"
      ],
