      "body": [
        "デリー＝スルタン朝は、圧倒的に人口の多いヒンドゥー教徒を支配するために、ヒンドゥー教徒の小国家に自治権を認めて、もともとのインド社会にほとんど手をつけなかった。一方で、<span class=\"source-red-bold\">スーフィズム</span>（<ruby><span class=\"source-red-bold\">神秘</span><rt>しんぴ</rt></ruby><span class=\"source-red-bold\">主義</span>）の活動が活発になったこともあって、インドではイスラーム教徒が増えていったんだけど、この時期、イスラーム教徒とヒンドゥー教徒は平和に共存していたよ。"
      ],
