      "title": "細密画と文学。本の中にも豊かな世界。",
      "body": [
        "こうしてヘラートやサマルカンドなどの都市では、イル＝ハン国のもとで発展した文化、例えば<ruby><span class=\"source-red-bold\">細密画</span><rt>さいみつが</rt></ruby>【<span class=\"source-red-bold\">ミニアチュール</span>】が普及したり、トルコ語の文学作品がつくられたり、さらに即位前のウルグ＝ベクがサマルカンドに天文台を建設して、当時もっとも精密な『ウルグ＝ベク天文表』を作成するなど、<span class=\"source-red-bold\">トルコ＝イスラーム文化</span>が栄えたよ。また、中央アジアのオアシス都市は、東西交易の一大拠点として繁栄した。ただ、シャー＝ルフの死後、一族の王子たちが各地で独立し、シャー＝ルフの息子ウルグ＝ベクが即位したけど、すぐに暗殺されてしまった。"
      ],
