      "title": "交易と財政が弱まり、各地で反乱が起こる。",
      "body": [
        "アッバース1世が亡くなったあと、17世紀にはほとんど戦争もなくサファヴィー朝は平和で安定していた。前近代のイランでこんなに戦争がなかったのはこの時代だけだよ。ただ、18世紀に入ると各地で経済が悪化し始めた。これって、ヨーロッパ諸国がアジアに進出したことで、サファヴィー朝の国際交易が衰退してきたことも一因だよ。こうした経済危機で王室の財政も悪化し、各地で反乱や暴動がたびたび起こると、ついに、<span class=\"source-bold\">アフガン人</span>にイスファハーンを占領されちゃった。"
      ],
      "plainBody": [
        "アッバース1世が亡くなったあと、17世紀にはほとんど戦争もなくサファヴィー朝は平和で安定していた。前近代のイランでこんなに戦争がなかったのはこの時代だけだよ。ただ、18世紀に入ると各地で経済が悪化し始めた。これって、ヨーロッパ諸国がアジアに進出したことで、サファヴィー朝の国際交易が衰退してきたことも一因だよ。こうした経済危機で王室の財政も悪化し、各地で反乱や暴動がたびたび起こると、ついに、アフガン人にイスファハーンを占領されちゃった。"
      ],
