      "title": "ガージャール朝が、テヘランを都に統一する。",
      "body": [
        "都を追われて権力を失ったサファヴィー朝は、トルコ系アフシャール人の<span class=\"source-bold\">ナーディル＝シャー</span>に滅ぼされた。ただ、ナーディル＝シャーが建てた<span class=\"source-bold\">アフシャール朝</span>も安定せず、アフガン人が<span class=\"source-bold\">ドゥッラーニー朝</span>を建てて自立するなど、各地で地方政権ができた。そして18世紀末、トルコ系の<span class=\"source-bold\">アーガー＝ムハンマド</span>が、<span class=\"source-bold\">テヘラン</span>を都に<span class=\"source-red-bold\">ガージャール朝</span>を建ててイランを統一した。このときのガージャール朝の支配領域がほぼ現在のイランで、ドゥッラーニー朝の支配領域がほぼ現在のアフガニスタンだよ。"
      ],
      "plainBody": [
        "都を追われて権力を失ったサファヴィー朝は、トルコ系アフシャール人のナーディル＝シャーに滅ぼされた。ただ、ナーディル＝シャーが建てたアフシャール朝も安定せず、アフガン人がドゥッラーニー朝を建てて自立するなど、各地で地方政権ができた。そして18世紀末、トルコ系のアーガー＝ムハンマドが、テヘランを都にガージャール朝を建ててイランを統一した。このときのガージャール朝の支配領域がほぼ現在のイランで、ドゥッラーニー朝の支配領域がほぼ現在のアフガニスタンだよ。"
      ],
