      "body": [
        "アウラングゼーブの死後、分裂はさらにひどくなった。デカン高原では、<ruby>宰相<rt>さいしょう</rt></ruby>の<span class=\"source-bold\">アーサフ＝ジャー</span>が自立して<span class=\"source-bold\">ニザーム王国</span>【<span class=\"source-bold\">ハイデラバード王国</span>】を建て、ガンジス川中流域でも<span class=\"source-bold\">アワド王国</span>【<span class=\"source-bold\">アウド王国</span>】が事実上独立した。また、北西部のパンジャーブ地方では<span class=\"source-red-bold\">シク王国</span>【<span class=\"source-red-bold\">シク教王国</span>】も自立し、さらにイランの<span class=\"source-bold\">アフシャール朝</span>にデリーを略奪されるなど、ムガル帝国の権威は地に落ちた。"
      ],
      "plainBody": [
        "アウラングゼーブの死後、分裂はさらにひどくなった。デカン高原では、宰相のアーサフ＝ジャーが自立してニザーム王国【ハイデラバード王国】を建て、ガンジス川中流域でもアワド王国【アウド王国】が事実上独立した。また、北西部のパンジャーブ地方ではシク王国【シク教王国】も自立し、さらにイランのアフシャール朝にデリーを略奪されるなど、ムガル帝国の権威は地に落ちた。"
      ],
