      "body": [
        "すると、マラーター王国が領土を拡大しながら北インドの大半を征服し、ヒンドゥー教徒の<ruby>諸侯<rt>しょこう</rt></ruby>たちが連合して<span class=\"source-red-bold\">マラーター同盟</span>ができた。南インドでも、ヒンドゥー教の地方政権だった<span class=\"source-red-bold\">マイソール王国</span>が急成長したんだ。こうして、ムガル帝国はデリーの周辺だけを支配する弱小勢力に転落してしまったよ。こんなにバラバラだったから、インドはヨーロッパの進出に対抗できなかったんだね。"
      ],
