      "body": [
        "ムガル帝国の支配下では、イスラーム文化とヒンドゥー文化の混ざった独自の<span class=\"source-red-bold\">インド＝イスラーム文化</span>が生まれたよ。美術では、イランの<ruby><span class=\"source-red-bold\">細密画</span><rt>さいみつが</rt></ruby>【<span class=\"source-red-bold\">ミニアチュール</span>】がインド絵画と融合して<span class=\"source-red-bold\">ムガル絵画</span>に発展し、さらにその影響を受けて、ヒンドゥー教徒がヴィシュヌ信仰など庶民的な題材を描く<span class=\"source-bold\">ラージプート絵画</span>も発達したよ。"
      ],
      "plainBody": [
        "ムガル帝国の支配下では、イスラーム文化とヒンドゥー文化の混ざった独自のインド＝イスラーム文化が生まれたよ。美術では、イランの細密画【ミニアチュール】がインド絵画と融合してムガル絵画に発展し、さらにその影響を受けて、ヒンドゥー教徒がヴィシュヌ信仰など庶民的な題材を描くラージプート絵画も発達したよ。"
      ],
